<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();if(!is_post())redirect_to('slides.php');verify_csrf($_POST['csrf']??'');$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT image_path FROM hero_slides WHERE id=?');$s->execute([$id]);$x=$s->fetch();$pdo->prepare('DELETE FROM hero_slides WHERE id=?')->execute([$id]);if($x)delete_upload($x['image_path']??null);flash('success','Hero slide deleted.');}redirect_to('slides.php');
